#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,W;scanf("%d %d",&n,&W);
vector<long long>dp(W+1,0);
for(int i=0;i<n;++i){int w;long long v;scanf("%d %lld",&w,&v);
for(int j=W;j>=w;--j)dp[j]=max(dp[j],dp[j-w]+v);}
printf("%lld\n",dp[W]);return 0;}

